func (s *Store) GetItems(listID string, checked *bool) ([]ItemRow, error) {
	query := `SELECT id, list_id, name, quantity, details, category, category_match_id, checked, manual_sort_index, store_ids, photo_ids, prices, category_assignments
	          FROM items WHERE list_id = ?`
	args := []any{listID}
	if checked != nil {
		if *checked {
			query += " AND checked = 1"
		} else {
			query += " AND checked = 0"
		}
	}
	query += " ORDER BY manual_sort_index, name"

	rows, err := s.db.Query(query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return scanItems(rows)
}

// FindItemByName finds an item in a list by name (case-insensitive).
func (s *Store) FindItemByName(listID, name string) (*ItemRow, error) {
	lower := strings.ToLower(name)
	rows, err := s.db.Query(
		`SELECT id, list_id, name, quantity, details, category, category_match_id, checked, manual_sort_index, store_ids, photo_ids, prices, category_assignments
		 FROM items WHERE list_id = ?`, listID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	items, err := scanItems(rows)
	if err != nil {
		return nil, err
	}

	// Exact match
	for i, it := range items {
		if strings.EqualFold(it.Name, name) {
			return &items[i], nil
		}
	}
	// Prefix match
	for i, it := range items {
		if strings.HasPrefix(strings.ToLower(it.Name), lower) {
			return &items[i], nil
		}
	}
	// Contains match
	for i, it := range items {
		if strings.Contains(strings.ToLower(it.Name), lower) {
			return &items[i], nil
		}
	}
	return nil, fmt.Errorf("item %q not found in list", name)
}

